//! Parity of the Rust statistics against MATLAB, on fixtures generated by
//! MATLAB R2025a.
//!
//! These are the tests that make "the app and the toolbox agree" a
//! checkable claim rather than an intention. The fixtures under
//! `tests/fixtures/` were produced by running the real `ranksum` and the
//! `fdr_bh` nested in `FDR_1D.m` over randomized inputs that deliberately
//! span the parts where implementations drift:
//!
//!   * both sides of the exact/approximate switch at n1 + n2 = 20,
//!   * heavy ties (integer-valued samples), light ties (rounded), and
//!     continuous data with none,
//!   * samples containing NaN, which must be dropped and not imputed,
//!   * FDR families containing NaN p-values, which must not count toward m.
//!
//! Regenerate with `scripts/gen_matlab_parity.m` if the MATLAB side ever
//! changes; a diff in these files is a deliberate decision, not a detail.

use dynamo_rs::stats::{fdr, ranksum::ranksum};

fn parse_vec(s: &str) -> Vec<f64> {
    s.split_whitespace()
        .map(|t| if t.eq_ignore_ascii_case("nan") { f64::NAN } else { t.parse().unwrap() })
        .collect()
}

/// Relative comparison that treats NaN == NaN, since "untestable" is a
/// result we care about matching exactly.
fn agrees(got: f64, want: f64, tol: f64) -> bool {
    if got.is_nan() || want.is_nan() {
        return got.is_nan() && want.is_nan();
    }
    let scale = want.abs().max(1e-300);
    (got - want).abs() / scale <= tol || (got - want).abs() <= 1e-15
}

#[test]
fn ranksum_matches_matlab_on_300_random_cases() {
    let body = include_str!("fixtures/parity_ranksum.csv");
    let mut n = 0usize;
    let mut worst = 0.0f64;
    let mut worst_case = String::new();
    for line in body.lines().skip(1) {
        let f: Vec<&str> = line.split(',').collect();
        assert_eq!(f.len(), 6, "malformed fixture row: {}", line);
        let case = f[0];
        let want: f64 = f[3].parse().unwrap();
        let x = parse_vec(f[4]);
        let y = parse_vec(f[5]);

        let got = ranksum(&x, &y).p;
        assert!(
            agrees(got, want, 1e-9),
            "case {} (n = {} vs {}): rust {:.17e} vs matlab {:.17e}",
            case, f[1], f[2], got, want
        );
        if want.is_finite() && want > 0.0 {
            let rel = (got - want).abs() / want;
            if rel > worst {
                worst = rel;
                worst_case = case.to_string();
            }
        }
        n += 1;
    }
    assert!(n >= 300, "expected the full fixture, got {} cases", n);
    eprintln!("ranksum parity: {} cases, worst relative error {:.3e} (case {})", n, worst, worst_case);
}

#[test]
fn fdr_matches_matlab_on_random_families() {
    let body = include_str!("fixtures/parity_fdr.csv");
    let mut n = 0usize;
    for line in body.lines().skip(1) {
        let f: Vec<&str> = line.split(',').collect();
        assert_eq!(f.len(), 5, "malformed fixture row");
        let case = f[0];
        let method = fdr::Method::parse(f[1]).expect("known method");
        let q: f64 = f[2].parse().unwrap();
        let p = parse_vec(f[3]);
        let want = parse_vec(f[4]);

        let got = fdr::adjust(&p, q, method);
        assert_eq!(got.p_adj.len(), want.len(), "case {}: length", case);
        for (i, (g, w)) in got.p_adj.iter().zip(want.iter()).enumerate() {
            assert!(
                agrees(*g, *w, 1e-12),
                "case {} ({:?}) index {}: rust {:.17e} vs matlab {:.17e}",
                case, method, i, g, w
            );
        }
        n += 1;
    }
    assert!(n >= 120, "expected the full fixture, got {} cases", n);
    eprintln!("fdr parity: {} families checked", n);
}

/// The exact branch is where a naive port goes wrong, so pin the split
/// explicitly rather than trusting the random draw to cover it.
#[test]
fn fixture_covers_both_sides_of_the_exact_switch() {
    let body = include_str!("fixtures/parity_ranksum.csv");
    let (mut small, mut large, mut tied) = (0, 0, 0);
    for line in body.lines().skip(1) {
        let f: Vec<&str> = line.split(',').collect();
        let x = parse_vec(f[4]);
        let y = parse_vec(f[5]);
        let n = x.iter().filter(|v| v.is_finite()).count()
            + y.iter().filter(|v| v.is_finite()).count();
        if n < 20 {
            small += 1;
        } else {
            large += 1;
        }
        let mut all: Vec<f64> = x.iter().chain(y.iter()).copied().filter(|v| v.is_finite()).collect();
        all.sort_by(|a, b| a.partial_cmp(b).unwrap());
        if all.windows(2).any(|w| w[0] == w[1]) {
            tied += 1;
        }
    }
    assert!(small >= 30, "too few exact-branch cases: {}", small);
    assert!(large >= 30, "too few approximate-branch cases: {}", large);
    assert!(tied >= 30, "too few tied cases: {}", tied);
    eprintln!("fixture coverage: {} exact, {} approximate, {} with ties", small, large, tied);
}
